const e='<i class="bi bi-check2 me-2"></i>Copied!';export function initCopyIcons(){const t=document.querySelectorAll(".copyIcon");Array.from(t).forEach(t=>{t.addEventListener("click",t=>{const n=t.currentTarget.dataset.copydata;navigator.clipboard.writeText(n),t.currentTarget.innerHTML=e})})}export function copyString(t,n){navigator.clipboard.writeText(n),t.forEach(t=>{t.disabled=!0;const n=t.innerHTML;t.innerHTML=e,setTimeout(()=>{t.innerHTML=n,t.disabled=!1},4e3)})}